import{_ as e,o as p,c as o,a5 as i}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"HJ17 坐标移动","description":"描述 开发一个坐标计算工具， A表示向左移动，D表示向右移动，W表示向上移动，S表示向下移动。从（0,0）点开始移动，从输入字符串里面读取一些坐标，并将最终输入结果输出到输出文件里面。 输入： 合法坐标为A(或者D或者W或者S) + 数字（两位以内） 坐标之间以;分隔。 非法坐标。","frontmatter":{"title":"HJ17 坐标移动","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 开发一个坐标计算工具， A表示向左移动，D表示向右移动，W表示向上移动，S表示向下移动。从（0,0）点开始移动，从输入字符串里面读取一些坐标，并将最终输入结果输出到输出文件里面。 输入： 合法坐标为A(或者D或者W或者S) + 数字（两位以内） 坐标之间以;分隔。 非法坐标。","sidebarWeight":100,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/多细节（简单）/HJ17 坐标移动.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/多细节（简单）/HJ17 坐标移动.md","filePath":"posts/前端面试与实战/03-算法训练/多细节（简单）/HJ17 坐标移动.md"}'),a={name:"posts/前端面试与实战/03-算法训练/多细节（简单）/HJ17 坐标移动.md"};function l(r,t,n,u,s,A){return p(),o("div",null,[...t[0]||(t[0]=[i('<div><h1 id="hj17-坐标移动" tabindex="-1">HJ17 坐标移动 <a class="header-anchor" href="#hj17-坐标移动" aria-label="Permalink to &quot;HJ17 坐标移动&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ17 坐标移动”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 描述 开发一个坐标计算工具， A表示向左移动，D表示向右移动，W表示向上移动，S表示向下移动。从（0,0）点开始移动，从输入字符串里面读取一些坐标，并将最终输入结果输出到输出文件里面。</p></blockquote><p>输入：</p><p>合法坐标为A(或者D或者W或者S) + 数字（两位以内）</p><p>坐标之间以;分隔。</p><p>非法坐标点需要进行丢弃。如AA10; A1A; $%$; YAD; 等。</p><p>下面是一个简单的例子 如：</p><p>A10;S20;W10;D30;X;A1A;B10A11;;A10;</p><p>处理过程：</p><p>起点（0,0）</p><ul><li><p>A10 = （-10,0）</p></li><li><p>S20 = (-10,-20)</p></li><li><p>W10 = (-10,-10)</p></li><li><p>D30 = (20,-10)</p></li><li><p>x = 无效</p></li><li><p>A1A = 无效</p></li><li><p>B10A11 = 无效</p></li><li><p>一个空 不影响</p></li><li><p>A10 = (10,-10)</p></li></ul><p>结果 （10， -10）</p><p>数据范围：每组输入的字符串长度满足 1 ≤ � ≤ 10000 1≤n≤10000 ，坐标保证满足</p><p>，且数字部分仅含正数 输入描述： 一行字符串</p><p>输出描述： 最终坐标，以逗号分隔</p><p>示例1 输入： A10;S20;W10;D30;X;A1A;B10A11;;A10; 复制 输出： 10,-10 复制 示例2 输入： ABC;AKL;DA1; 复制 输出： 0,0</p><p>合法的情况处理，不合法的情况跳过 import re input_operation = input().strip().split(&quot;;&quot;) pattern = re.compile(&quot;^[ADWS][0-9]{1,2}$&quot;) # 正则表达式匹配合法坐标 x, y = 0, 0 for operation in input_operation:</p><h1 id="使用正则表达式验证指令是否合法" tabindex="-1">使用正则表达式验证指令是否合法 <a class="header-anchor" href="#使用正则表达式验证指令是否合法" aria-label="Permalink to &quot;使用正则表达式验证指令是否合法&quot;">​</a></h1><p>if pattern.match(operation): direction = operation[0] value = int(operation[1:]) if direction == &quot;A&quot;: x -= value elif direction == &quot;D&quot;: x += value elif direction == &quot;W&quot;: y += value elif direction == &quot;S&quot;: y -= value print(f&quot;{x},{y}&quot;)</p></div>',1)])])}const _=e(a,[["render",l]]);export{d as __pageData,_ as default};
